package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type Decl struct {
	Pkg      string
	Recv     string
	Name     string
	Path     string
	Exported bool
	IsMethod bool
}

type Call struct {
	File string
	Fun  string
}

func recvName(fl *ast.FieldList) string {
	if fl == nil || len(fl.List) == 0 {
		return ""
	}
	t := fl.List[0].Type
	if se, ok := t.(*ast.StarExpr); ok {
		t = se.X
	}
	if id, ok := t.(*ast.Ident); ok {
		return id.Name
	}
	if ix, ok := t.(*ast.IndexExpr); ok {
		if id, ok := ix.X.(*ast.Ident); ok {
			return id.Name
		}
	}
	return fmt.Sprintf("%T", t)
}

func funString(e ast.Expr) string {
	switch x := e.(type) {
	case *ast.Ident:
		return x.Name
	case *ast.SelectorExpr:
		if id, ok := x.X.(*ast.Ident); ok {
			return id.Name + "." + x.Sel.Name
		}
		return "*." + x.Sel.Name
	case *ast.IndexExpr:
		return funString(x.X)
	default:
		return ""
	}
}

func main() {
	root := "/bench/repo"
	fset := token.NewFileSet()

	var decls []Decl
	type callRec struct {
		file, pkg, sel, ident string
		isSel                 bool
	}
	var calls []callRec

	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			base := info.Name()
			if base == "vendor" || base == "node_modules" || base == ".git" || base == "web" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		f, err := parser.ParseFile(fset, path, nil, parser.SkipObjectResolution)
		if err != nil {
			fmt.Fprintf(os.Stderr, "parse %s: %v\n", path, err)
			return nil
		}
		pkg := f.Name.Name
		rel, _ := filepath.Rel(root, path)
		underInternal := strings.HasPrefix(rel, "internal"+string(os.PathSeparator))

		if underInternal {
			for _, d := range f.Decls {
				fd, ok := d.(*ast.FuncDecl)
				if !ok || fd.Name == nil {
					continue
				}
				recv := recvName(fd.Recv)
				decls = append(decls, Decl{
					Pkg:      pkg,
					Recv:     recv,
					Name:     fd.Name.Name,
					Path:     rel,
					Exported: ast.IsExported(fd.Name.Name),
					IsMethod: recv != "",
				})
			}
		}

		ast.Inspect(f, func(n ast.Node) bool {
			ce, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			switch fn := ce.Fun.(type) {
			case *ast.Ident:
				calls = append(calls, callRec{file: rel, pkg: pkg, ident: fn.Name, isSel: false})
			case *ast.SelectorExpr:
				pkgOrRecv := ""
				if id, ok := fn.X.(*ast.Ident); ok {
					pkgOrRecv = id.Name
				}
				calls = append(calls, callRec{file: rel, pkg: pkg, sel: pkgOrRecv, ident: fn.Sel.Name, isSel: true})
			}
			return true
		})
		return nil
	})
	if err != nil {
		panic(err)
	}

	// Count fan-in with several matching strategies
	type key struct {
		pkg, recv, name, path string
	}

	// Strategy A: unique (pkg, name) for funcs; (name) for methods with recv
	// Cross-package: SelectorExpr where X == pkg && Sel == name
	// Same-package: Ident == name
	// Methods: SelectorExpr Sel == name (any X)

	countsExact := map[key]int{}
	countsName := map[string]int{}
	countsPkgName := map[string]int{}

	// Build lookup
	pkgFuncs := map[string]map[string][]Decl{} // pkg -> name -> decls
	methodNames := map[string][]Decl{}
	for _, d := range decls {
		if !d.IsMethod {
			if pkgFuncs[d.Pkg] == nil {
				pkgFuncs[d.Pkg] = map[string][]Decl{}
			}
			pkgFuncs[d.Pkg][d.Name] = append(pkgFuncs[d.Pkg][d.Name], d)
		} else {
			methodNames[d.Name] = append(methodNames[d.Name], d)
		}
	}

	for _, c := range calls {
		if !c.isSel {
			// same-package function call
			if m, ok := pkgFuncs[c.pkg]; ok {
				for _, d := range m[c.ident] {
					k := key{d.Pkg, d.Recv, d.Name, d.Path}
					countsExact[k]++
				}
			}
		} else {
			// pkg.Func or recv.Method
			if m, ok := pkgFuncs[c.sel]; ok {
				for _, d := range m[c.ident] {
					k := key{d.Pkg, d.Recv, d.Name, d.Path}
					countsExact[k]++
				}
			}
			// also method by name
			for _, d := range methodNames[c.ident] {
				k := key{d.Pkg, d.Recv, d.Name, d.Path}
				countsExact[k]++
			}
		}
		countsName[c.ident]++
		if c.isSel && c.sel != "" {
			countsPkgName[c.sel+"."+c.ident]++
		} else if !c.isSel {
			countsPkgName[c.pkg+"."+c.ident]++
		}
	}

	type row struct {
		d     Decl
		count int
	}
	var rows []row
	seen := map[string]bool{}
	for _, d := range decls {
		k := key{d.Pkg, d.Recv, d.Name, d.Path}
		id := fmt.Sprintf("%s %s %s %s", d.Pkg, d.Recv, d.Name, d.Path)
		if seen[id] {
			continue
		}
		seen[id] = true
		rows = append(rows, row{d, countsExact[k]})
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].count > rows[j].count })

	fmt.Println("=== Top 40 by AST-matched fan-in (pkg.func + same-pkg ident; methods by name) ===")
	for i, r := range rows {
		if i >= 40 {
			break
		}
		sym := r.d.Name
		if r.d.Recv != "" {
			sym = "(" + r.d.Recv + ")." + r.d.Name
		}
		fmt.Printf("%4d  %-40s  %s  pkg=%s\n", r.count, sym, r.d.Path, r.d.Pkg)
	}

	// Also show top function names among internal decls by raw name count
	fmt.Println("\n=== Top internal-declared names by raw ident/selector call count ===")
	nameSet := map[string][]Decl{}
	for _, d := range decls {
		nameSet[d.Name] = append(nameSet[d.Name], d)
	}
	type nr struct {
		name  string
		count int
		decls []Decl
	}
	var nrs []nr
	for name, ds := range nameSet {
		nrs = append(nrs, nr{name, countsName[name], ds})
	}
	sort.Slice(nrs, func(i, j int) bool { return nrs[i].count > nrs[j].count })
	for i, r := range nrs {
		if i >= 30 {
			break
		}
		paths := []string{}
		for _, d := range r.decls {
			recv := d.Name
			if d.Recv != "" {
				recv = "(" + d.Recv + ")." + d.Name
			}
			paths = append(paths, recv+"@"+d.Path)
		}
		fmt.Printf("%4d  %s  %s\n", r.count, r.name, strings.Join(paths, " | "))
	}

	fmt.Printf("\nTotal decls: %d  Total calls: %d\n", len(decls), len(calls))
}
EOF
