cat > /tmp/fanin.pl << 'ENDSCRIPT'
#!/usr/bin/perl
use strict;
use warnings;
use File::Find;

my $root = "/bench/repo";

# Collect all .go files except web, vendor, .git
my @gofiles;
find({
    wanted => sub {
        return unless /\.go$/;
        my $p = $File::Find::name;
        return if $p =~ m{/\.git/} || $p =~ m{/vendor/} || $p =~ m{/web/} || $p =~ m{/node_modules/};
        push @gofiles, $p;
    },
    no_chdir => 1,
}, $root);

print "Go files: ", scalar(@gofiles), "\n";

# Extract declarations from internal/
my @decls;
for my $file (@gofiles) {
    my $rel = $file;
    $rel =~ s{^\Q$root\E/}{};
    next unless $rel =~ m{^internal/};
    open my $fh, "<", $file or die $!;
    my $src = do { local $/; <$fh> };
    close $fh;
    # strip comments roughly
    $src =~ s{/\*.*?\*/}{}sg;
    $src =~ s{//.*$}{}mg;

    my $pkg = "unknown";
    if ($src =~ /^package\s+(\w+)/m) { $pkg = $1; }

    while ($src =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*(?:\[|\()/mg) {
        my ($recv, $name) = ($1 // "", $2);
        $recv =~ s/\s+/ /g;
        $recv =~ s/^\s+|\s+$//g;
        # extract type
        my $rtype = "";
        if ($recv =~ /\*?\s*(\w+)/) {
            # last ident is usually the type
            my @parts = split /\s+/, $recv;
            $rtype = $parts[-1];
            $rtype =~ s/^\*//;
            $rtype =~ s/\[.*//;
        }
        push @decls, {
            pkg => $pkg,
            recv => $rtype,
            recv_raw => $recv,
            name => $name,
            path => $rel,
            is_method => ($recv ne ""),
        };
    }
}

print "Decls: ", scalar(@decls), "\n";

# Read all sources and extract calls
my @calls; # {file, pkg, sel, name, is_sel}
for my $file (@gofiles) {
    my $rel = $file;
    $rel =~ s{^\Q$root\E/}{};
    open my $fh, "<", $file or die $!;
    my $src = do { local $/; <$fh> };
    close $fh;
    $src =~ s{/\*.*?\*/}{}sg;
    $src =~ s{//.*$}{}mg;
    # strip raw strings and interpreted strings roughly to reduce false positives
    $src =~ s/`[^`]*`/ /sg;
    $src =~ s/"(?:\\.|[^"\\])*"/ /sg;

    my $pkg = "unknown";
    if ($src =~ /^package\s+(\w+)/m) { $pkg = $1; }

    # selector calls: ident.Name(  or  ).Name(
    while ($src =~ /(?:(\w+)|(?:\)|\]))\s*\.\s*(\w+)\s*(?:\[|\()/g) {
        my ($sel, $name) = ($1 // "", $2);
        push @calls, { file => $rel, pkg => $pkg, sel => $sel, name => $name, is_sel => 1 };
    }
    # ident calls: Name( but not after . 
    # We'll collect all word( and subtract those that were selectors... 
    # simpler: match (?<![.\w])Name(
    while ($src =~ /(?<![.\w])(\w+)\s*(?:\[.*?\])?\s*\(/g) {
        my $name = $1;
        next if $name =~ /^(if|for|switch|func|return|go|defer|select|range|make|new|append|len|cap|copy|delete|close|panic|recover|complex|real|imag|min|max)$/;
        push @calls, { file => $rel, pkg => $pkg, sel => "", name => $name, is_sel => 0 };
    }
}

print "Call-like sites: ", scalar(@calls), "\n";

# Index decls
my %pkg_funcs; # pkg -> name -> [decls]
my %methods;   # name -> [decls]
my %all_by_key;
for my $d (@decls) {
    if ($d->{is_method}) {
        push @{$methods{$d->{name}}}, $d;
    } else {
        push @{$pkg_funcs{$d->{pkg}}{$d->{name}}}, $d;
    }
