            pkg => $pkg, recv => $rtype, name => $name, path => $rel,
            is_method => ($recv ne ""), is_test_file => $is_test, line => $ln,
            is_test_func => ($name =~ /^(Test|Benchmark|Example|Fuzz)/),
        };
        push @func_spans, $d;
        if ($under_int) {
            push @all_internal_decls, $d;
            if (!$is_test && !$d->{is_test_func} && $name ne "init") {
                push @decls, $d;
            }
        }
    }

    my $src = strip($raw);
    # Walk calls and assign to enclosing func by line
    my @calls;
    while ($src =~ /(?:(\w+)|(?:\)|\]))\s*\.\s*(\w+)\s*(?:\[|\()/g) {
        my ($sel, $name) = ($1 // "", $2);
        my $before = substr($src, 0, $-[0]);
        my $ln = ($before =~ tr/\n//) + 1;
        push @calls, { sel => $sel, name => $name, is_sel => 1, line => $ln };
    }
    while ($src =~ /(?<![.\w])(\w+)\s*\(/g) {
        my $name = $1;
        next if $name =~ /^(if|for|switch|func|return|go|defer|select|range|make|new|append|len|cap|copy|delete|close|panic|recover|complex|real|imag|min|max|var|type|map|chan|interface|struct)$/;
        my $before = substr($src, 0, $-[0]);
        my $ln = ($before =~ tr/\n//) + 1;
        push @calls, { sel => "", name => $name, is_sel => 0, line => $ln };
    }

    # enclosing function: last func whose start_line <= call line
    for my $c (@calls) {
        my $enc = "<pkg>";
        for my $f (@func_spans) {
            if ($f->{line} <= $c->{line}) {
                $enc = $f->{name};
            } else {
                last;
            }
        }
        push @events, {
            file => $rel, pkg => $pkg, sel => $c->{sel}, name => $c->{name},
            is_sel => $c->{is_sel}, line => $c->{line}, caller => $enc,
            is_test => $is_test,
        };
    }
}

print "Production decls: ", scalar(@decls), "  All internal decls: ", scalar(@all_internal_decls), "  Events: ", scalar(@events), "\n";

sub dkey {
    my $d = shift;
    return join("|", $d->{pkg}, $d->{recv}, $d->{name}, $d->{path});
}

my %pkg_funcs;
my %methods_samepkg; # only production methods
for my $d (@decls) {
    if ($d->{is_method}) {
        push @{$methods_samepkg{$d->{pkg}}{$d->{name}}}, $d;
    } else {
        push @{$pkg_funcs{$d->{pkg}}{$d->{name}}}, $d;
    }
}

# Count
my %sites;   # key -> count of call sites
my %callers; # key -> {caller_file:func}
my %files;   # key -> {file}
my %prod_sites;
my %prod_callers;

for my $e (@events) {
    my @matched;
    if (!$e->{is_sel}) {
        if (my $m = $pkg_funcs{$e->{pkg}}{$e->{name}}) {
            @matched = @$m;
        }
    } else {
        # package.Func
        if ($e->{sel} && (my $m = $pkg_funcs{$e->{sel}}{$e->{name}})) {
            push @matched, @$m;
        }
        # method only if same package
        if (my $ms = $methods_samepkg{$e->{pkg}}{$e->{name}}) {
            push @matched, @$ms;
        }
    }
    for my $d (@matched) {
        # skip if the "call" is the declaration line itself
        next if $e->{file} eq $d->{path} && $e->{line} == $d->{line};
        my $k = dkey($d);
        $sites{$k}++;
        $callers{$k}{"$e->{file}:$e->{caller}"} = 1;
        $files{$k}{$e->{file}} = 1;
        if (!$e->{is_test}) {
            $prod_sites{$k}++;
            $prod_callers{$k}{"$e->{file}:$e->{caller}"} = 1;
        }
    }
}

sub dump_top {
    my ($title, $hash, $n) = @_;
    print "\n=== $title ===\n";
    my @rows;
    for my $d (@decls) {
        my $k = dkey($d);
        push @rows, { d => $d, n => ($hash->{$k} ? (ref $hash->{$k} eq 'HASH' ? scalar(keys %{$hash->{$k}}) : $hash->{$k}) : 0) };
    }
    @rows = sort { $b->{n} <=> $a->{n} || $a->{d}{name} cmp $b->{d}{name} } @rows;
    my $i = 0;
    for my $r (@rows) {
        last if $i++ >= $n;
        my $d = $r->{d};
        my $sym = $d->{is_method} ? "($d->{recv}).$d->{name}" : $d->{name};
        printf "%4d  %-50s  %s\n", $r->{n}, $sym, $d->{path};
    }
}

dump_top("Top unique callers (incl tests)", \%callers, 25);
dump_top("Top call sites (incl tests)", \%sites, 25);
dump_top("Top unique callers (prod only)", \%prod_callers, 25);
dump_top("Top call sites (prod only)", \%prod_sites, 25);

# Also show caller lists for top 8 by unique callers
print "\n=== Caller lists for top unique-caller symbols ===\n";
my @top;
for my $d (@decls) {
    my $k = dkey($d);
    push @top, { d => $d, n => scalar(keys %{$callers{$k}||{}}) };
}
@top = sort { $b->{n} <=> $a->{n} } @top;
for my $i (0..9) {
    my $d = $top[$i]{d};
    my $k = dkey($d);
    my $sym = $d->{is_method} ? "($d->{recv}).$d->{name}" : $d->{name};
    print "\n$sym @ $d->{path}  callers=$top[$i]{n} sites=$sites{$k}\n";
    for my $c (sort keys %{$callers{$k}}) {
        print "    $c\n";
    }
}
